import itertools, json, sys, random

def reduce_instance(instance):
    m = instance['num_vars']
    clauses = instance['clauses']
    # vertices: 0=T,1=F,2=B
    edges = set()
    def add(u,v):
        if u==v: return
        if u>v: u,v=v,u
        edges.add((u,v))
    # triangle
    add(0,1); add(1,2); add(0,2)
    lit_vertex = {}
    next_idx = 3
    for i in range(1,m+1):
        vt = next_idx; vf = next_idx+1
        lit_vertex[(i, True)] = vt
        lit_vertex[(i, False)] = vf
        next_idx += 2
        # variable gadget edges
        add(vt, vf)
        add(vt, 1)  # vt adjacent to FALSE vertex
        add(vf, 0)  # vf adjacent to TRUE vertex
    # clause vertices
    for clause in clauses:
        c = next_idx; next_idx+=1
        # connect to base
        add(c,2)
        for lit in clause:
            sign = lit[0]
            var = int(lit[1:])
            v = lit_vertex[(var, sign=='+')]
            add(c, v)
    n = next_idx
    edges_list = [list(e) for e in edges]
    return {'n': n, 'edges': edges_list}

def is_sat(instance):
    m=instance['num_vars']; clauses=instance['clauses']
    for assign in itertools.product([False,True], repeat=m):
        ok=True
        for clause in clauses:
            clause_ok=False
            for lit in clause:
                sign=lit[0]; var=int(lit[1:])
                val=assign[var-1]
                if (sign=='+' and val) or (sign=='-' and not val):
                    clause_ok=True; break
            if not clause_ok:
                ok=False; break
        if ok:
            return True
    return False

def is_3colorable(g):
    n=g['n']; edges=g['edges']
    adj=[set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    colors=[-1]*n
    def dfs(v):
        if v==n:
            return True
        for c in range(3):
            if all(colors[w]!=c for w in adj[v]):
                colors[v]=c
                if dfs(v+1):
                    return True
        colors[v]=-1
        return False
    return dfs(0)

# test random small instances
random.seed(0)
for m in range(0,4):
    for _ in range(100):
        # generate random clauses ensuring each clause has 3 distinct vars
        clauses=[]
        num_clauses=random.randint(0,3)
        for __ in range(num_clauses):
            vars=random.sample(range(1,m+1), k=3) if m>=3 else []
            if not vars:
                continue
            clause=[]
            for v in vars:
                sign=random.choice(['+','-'])
                clause.append(sign+str(v))
            clauses.append(clause)
        instance={'num_vars':m,'clauses':clauses}
        sat=is_sat(instance)
        g=reduce_instance(instance)
        col=is_3colorable(g)
        if sat!=col:
            print('Mismatch', instance, sat, col)
            sys.exit()
print('All good')
PY"}

